import * as React from 'react';
import * as FloatingDockPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface FloatingDockProps extends React.ComponentPropsWithoutRef<typeof FloatingDockPrimitive.FloatingDock> {
  className?: string;
}

export const FloatingDock = React.forwardRef<HTMLDivElement, FloatingDockProps>(
  ({ className, children, ...props }, ref) => (
    <FloatingDockPrimitive.FloatingDock
      ref={ref}
      className={clsx(
        'mx-auto flex h-16 items-end gap-3 rounded-2xl border border-border bg-card/80 px-4 pb-3 shadow-lg backdrop-blur-md',
        className
      )}
      {...props}
    >
      {children}
    </FloatingDockPrimitive.FloatingDock>
  )
);
FloatingDock.displayName = 'FloatingDock';

